/** In-memory live state of the service, streamed to the web UI over SSE. */

export type WorkerState = {
  id: string;
  status: "idle" | "busy";
  task: string | null;
  since: string;
  processed: number;
  failed: number;
  lastError: string | null;
};

export type PoolState = { name: string; title: string; queued: number; processed: number; failed: number; workers: WorkerState[] };

export type RunState = {
  id: number;
  trigger: string;
  stage: string;
  startedAt: string;
  selected: number;
  scraped: number;
  failed: number;
};

export type MonitorEvent = { at: string; level: "info" | "warn" | "error"; msg: string };

export interface PoolLike {
  state(): PoolState;
}

class Monitor {
  readonly pools: PoolLike[] = [];
  run: RunState | null = null;
  nextRunAt: () => Date | null = () => null;
  private events: MonitorEvent[] = [];
  private listeners = new Set<() => void>();

  event(level: MonitorEvent["level"], msg: string) {
    this.events.push({ at: new Date().toISOString(), level, msg });
    if (this.events.length > 200) this.events.shift();
    this.changed();
  }

  setStage(stage: string) {
    if (this.run) this.run.stage = stage;
    this.changed();
  }

  changed() {
    for (const l of this.listeners) l();
  }

  subscribe(fn: () => void) {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  snapshot() {
    return {
      now: new Date().toISOString(),
      run: this.run,
      nextRunAt: this.nextRunAt()?.toISOString() ?? null,
      pools: this.pools.map((p) => p.state()),
      events: this.events.slice(-60).reverse(),
    };
  }
}

export const monitor = new Monitor();

import { log } from "../lib/log";
import { errorMessage } from "../lib/util";
import { type PoolLike, type PoolState, type WorkerState, monitor } from "./monitor";

/**
 * A named pool of long-lived async workers consuming an in-memory queue.
 * Each worker reports its status to the monitor; `drain()` waits until the queue is empty and all workers are idle.
 */
export class WorkerPool<T> implements PoolLike {
  private queue: T[] = [];
  private wakeups: (() => void)[] = [];
  private drainWaiters: (() => void)[] = [];
  private workers: WorkerState[];
  private busy = 0;

  constructor(
    readonly name: string,
    readonly title: string,
    size: number,
    private handler: (job: T) => Promise<void>,
    private label: (job: T) => string,
  ) {
    this.workers = Array.from({ length: size }, (_, i) => ({
      id: `${name}-${i + 1}`,
      status: "idle",
      task: null,
      since: new Date().toISOString(),
      processed: 0,
      failed: 0,
      lastError: null,
    }));
    monitor.pools.push(this);
    for (const w of this.workers) void this.loop(w);
  }

  push(job: T) {
    this.queue.push(job);
    this.wakeups.shift()?.();
    monitor.changed();
  }

  drain(): Promise<void> {
    if (this.isIdle()) return Promise.resolve();
    return new Promise((r) => this.drainWaiters.push(r));
  }

  private isIdle() {
    return this.queue.length === 0 && this.busy === 0;
  }

  private async next(): Promise<T> {
    while (this.queue.length === 0) await new Promise<void>((r) => this.wakeups.push(r));
    return this.queue.shift()!;
  }

  private async loop(w: WorkerState) {
    for (;;) {
      const job = await this.next();
      this.busy++;
      Object.assign(w, { status: "busy", task: this.label(job), since: new Date().toISOString() });
      monitor.changed();
      try {
        await this.handler(job);
        w.processed++;
      } catch (e) {
        w.failed++;
        w.lastError = errorMessage(e);
        log.error(`${w.id}: ${this.label(job)} — ${w.lastError}`);
      } finally {
        this.busy--;
        Object.assign(w, { status: "idle", task: null, since: new Date().toISOString() });
        if (this.isIdle()) this.drainWaiters.splice(0).forEach((r) => r());
        monitor.changed();
      }
    }
  }

  state(): PoolState {
    return {
      name: this.name,
      title: this.title,
      queued: this.queue.length,
      processed: this.workers.reduce((s, w) => s + w.processed, 0),
      failed: this.workers.reduce((s, w) => s + w.failed, 0),
      workers: this.workers,
    };
  }
}

import { and, eq } from "drizzle-orm";
import { db } from "../db/client";
import { dailyProgress, processedGames } from "../db/schema";
import { log } from "../lib/log";
import { today } from "../lib/util";
import { fetchBrowsePage, fetchNewReleases } from "../metacritic/api";

export type SelectedGame = { slug: string; title: string; source: "new-releases" | "browse" };

const MAX_PAGES_PER_RUN = 15;

/**
 * Picks the next N games not yet processed today:
 *   1) the 20 "New Releases" from /game/ (once per day),
 *   2) then consecutive pages of "See All → Newest", resuming from today's page cursor.
 * A new calendar day starts a fresh progress row, so the order restarts from step 1.
 * Selected slugs are recorded immediately so a game is never picked twice in one day, even if it later fails.
 */
export async function selectGames(n: number, runId: number): Promise<SelectedGame[]> {
  const day = today();
  const progress =
    db.select().from(dailyProgress).where(eq(dailyProgress.day, day)).get() ??
    db.insert(dailyProgress).values({ day }).returning().get();

  const seen = new Set(
    db.select({ slug: processedGames.slug }).from(processedGames).where(eq(processedGames.day, day)).all().map((r) => r.slug),
  );
  const picked: SelectedGame[] = [];
  const take = (items: { slug: string; title: string }[], source: SelectedGame["source"]) => {
    const fresh = items.filter((i) => !seen.has(i.slug));
    for (const i of fresh.slice(0, n - picked.length)) {
      seen.add(i.slug);
      picked.push({ slug: i.slug, title: i.title, source });
    }
    return fresh.length;
  };

  let { newReleasesDone, browsePage } = progress;
  if (!newReleasesDone) {
    take(await fetchNewReleases(), "new-releases");
    newReleasesDone = true;
    log.info(`selection: ${picked.length} games from New Releases`);
  }

  for (let i = 0; picked.length < n && i < MAX_PAGES_PER_RUN; i++) {
    const items = await fetchBrowsePage(browsePage);
    if (!items.length) break;
    const before = picked.length;
    const fresh = take(items, "browse");
    log.info(`selection: browse page ${browsePage} → ${picked.length - before} new games`);
    // Move the cursor only once a page is fully consumed; otherwise resume from it next run.
    if (picked.length - before === fresh) browsePage++;
    else break;
  }

  db.transaction((tx) => {
    tx.update(dailyProgress).set({ newReleasesDone, browsePage }).where(eq(dailyProgress.day, day)).run();
    for (const g of picked) {
      tx.insert(processedGames).values({ day, slug: g.slug, source: g.source, runId }).onConflictDoNothing().run();
    }
  });
  return picked;
}

export function markProcessed(slug: string, status: "ok" | "failed") {
  db.update(processedGames)
    .set({ status })
    .where(and(eq(processedGames.day, today()), eq(processedGames.slug, slug)))
    .run();
}

