      <section class="panel">
        <h2>Платформы и оценки</h2>
        <table class="platforms">
          <thead>
            <tr>
              <th>Платформа</th>
              <th>Metascore</th>
              <th>Критиков</th>
              <th>User score</th>
              <th>Игроков</th>
