import { db } from "../db/client";
import { games, similarGames } from "../db/schema";

const TOP_K = 6;
const MIN_SCORE = 0.08;

const STOP = new Set(
  "a an the and or of to in on for with by from at as is are be this that it its your you their they will can into up out all new game games play player players world".split(
    " ",
  ),
);

const words = (s: string | null) =>
  (s ?? "")
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, " ")
    .split(/\s+/)
    .filter((w) => w.length > 2 && !STOP.has(w));

/**
 * Content-based similarity: TF-IDF over description words plus weighted genre / developer / publisher tokens,
 * cosine similarity between all games. Cheap enough to recompute for the whole catalogue after each run.
 */
export function recomputeSimilarity(): number {
  const rows = db
    .select({ id: games.id, description: games.description, genres: games.genres, developer: games.developer, publisher: games.publisher })
    .from(games)
    .all();

  const docs = rows.map((g) => {
    const tf = new Map<string, number>();
    const add = (t: string, w: number) => tf.set(t, (tf.get(t) ?? 0) + w);
    for (const w of words(g.description)) add(w, 1);
    for (const genre of g.genres) add(`genre:${genre.toLowerCase()}`, 4);
    for (const d of (g.developer ?? "").split(",").filter(Boolean)) add(`dev:${d.trim().toLowerCase()}`, 3);
    for (const p of (g.publisher ?? "").split(",").filter(Boolean)) add(`pub:${p.trim().toLowerCase()}`, 1);
    return { id: g.id, tf };
  });

  const df = new Map<string, number>();
  for (const d of docs) for (const t of d.tf.keys()) df.set(t, (df.get(t) ?? 0) + 1);

  const vectors = docs.map((d) => {
    const v = new Map<string, number>();
    let norm = 0;
    for (const [t, f] of d.tf) {
      const w = (1 + Math.log(f)) * Math.log((1 + docs.length) / (1 + (df.get(t) ?? 0)) + 1);
      v.set(t, w);
      norm += w * w;
    }
    norm = Math.sqrt(norm) || 1;
    for (const [t, w] of v) v.set(t, w / norm);
    return { id: d.id, v };
  });

  const result: { gameId: number; similarId: number; score: number }[] = [];
  for (const a of vectors) {
    const scored: { id: number; score: number }[] = [];
    for (const b of vectors) {
      if (a.id === b.id) continue;
      let dot = 0;
      const [small, large] = a.v.size < b.v.size ? [a.v, b.v] : [b.v, a.v];
      for (const [t, w] of small) dot += w * (large.get(t) ?? 0);
      if (dot >= MIN_SCORE) scored.push({ id: b.id, score: dot });
    }
    scored.sort((x, y) => y.score - x.score);
    for (const s of scored.slice(0, TOP_K)) result.push({ gameId: a.id, similarId: s.id, score: s.score });
  }

  db.transaction((tx) => {
    tx.delete(similarGames).run();
    for (let i = 0; i < result.length; i += 500) tx.insert(similarGames).values(result.slice(i, i + 500)).run();
  });
  return result.length;
}

