4	const TOP_K = 6;
5	const MIN_SCORE = 0.12;
6	// Final score = weighted mix of three interpretable signals.
7	const W_TEXT = 0.55; // TF-IDF cosine of descriptions
8	const W_GENRE = 0.35; // Jaccard overlap of genres
9	const W_STUDIO = 0.1; // shared developer
10	
11	const STOP = new Set(
12	  "a an the and or of to in on for with by from at as is are be this that it its your you their they will can into up out all new game games play player players world more than through".split(
13	    " ",
14	  ),
15	);
16	
17	const words = (s: string | null) =>
18	  (s ?? "")
19	    .toLowerCase()
20	    .replace(/[^\p{L}\p{N}\s]/gu, " ")
21	    .split(/\s+/)
22	    .filter((w) => w.length > 2 && !STOP.has(w));
23	
24	const lowerSet = (items: string[]) => new Set(items.map((s) => s.trim().toLowerCase()).filter(Boolean));
25	
26	function jaccard(a: Set<string>, b: Set<string>): number {
27	  if (!a.size || !b.size) return 0;
28	  let inter = 0;
29	  for (const x of a) if (b.has(x)) inter++;
30	  return inter / (a.size + b.size - inter);
31	}
32	
33	function tfidfVectors(docs: string[][]): Map<string, number>[] {
34	  const df = new Map<string, number>();
35	  for (const d of docs) for (const t of new Set(d)) df.set(t, (df.get(t) ?? 0) + 1);
36	  return docs.map((d) => {
37	    const tf = new Map<string, number>();
38	    for (const t of d) tf.set(t, (tf.get(t) ?? 0) + 1);
39	    const v = new Map<string, number>();
40	    let norm = 0;
41	    for (const [t, f] of tf) {
42	      const w = (1 + Math.log(f)) * Math.log((1 + docs.length) / (1 + (df.get(t) ?? 0)) + 1);
43	      v.set(t, w);
44	      norm += w * w;
45	    }
46	    norm = Math.sqrt(norm) || 1;
47	    for (const [t, w] of v) v.set(t, w / norm);
48	    return v;
49	  });
50	}
51	
52	function cosine(a: Map<string, number>, b: Map<string, number>): number {
53	  const [small, large] = a.size < b.size ? [a, b] : [b, a];
54	  let dot = 0;
55	  for (const [t, w] of small) dot += w * (large.get(t) ?? 0);
56	  return dot;
57	}
58	
59	/**
60	 * Content-based "similar games": description TF-IDF cosine + genre overlap + same studio.
61	 * Cheap enough to recompute for the whole catalogue after each run.
62	 */
63	export function recomputeSimilarity(): number {
64	  const rows = db.select({ id: games.id, description: games.description, genres: games.genres, developer: games.developer }).from(games).all();
65	
66	  const text = tfidfVectors(rows.map((g) => words(g.description)));
67	  const genres = rows.map((g) => lowerSet(g.genres));
68	  const studios = rows.map((g) => lowerSet((g.developer ?? "").split(",")));
69	
70	  const result: { gameId: number; similarId: number; score: number }[] = [];
71	  rows.forEach((a, i) => {
72	    const scored: { id: number; score: number }[] = [];
73	    rows.forEach((b, j) => {
74	      if (i === j) return;
75	      const score =
76	        W_TEXT * cosine(text[i]!, text[j]!) +
77	        W_GENRE * jaccard(genres[i]!, genres[j]!) +
78	        W_STUDIO * (jaccard(studios[i]!, studios[j]!) > 0 ? 1 : 0);
79	      if (score >= MIN_SCORE) scored.push({ id: b.id, score });
80	    });
81	    scored.sort((x, y) => y.score - x.score);
82	    for (const s of scored.slice(0, TOP_K)) result.push({ gameId: a.id, similarId: s.id, score: s.score });
83	  });
84	
85	  db.transaction((tx) => {
86	    tx.delete(similarGames).run();
87	    for (let i = 0; i < result.length; i += 500) tx.insert(similarGames).values(result.slice(i, i + 500)).run();
88	  });
89	  return result.length;
90	}
