8	export function ytdlp(args: string[], timeoutMs = 120_000): Promise<string> {
9	  return new Promise((resolve, reject) => {
10	    const proc = spawn(config.YTDLP_PATH, ["--no-warnings", "--no-progress", "--js-runtimes", "node", ...args], { windowsHide: true });
11	    let out = "";
12	    let err = "";
13	    const timer = setTimeout(() => {
14	      proc.kill();
15	      reject(new Error(`yt-dlp timed out after ${timeoutMs} ms`));
16	    }, timeoutMs);
17	    proc.stdout.on("data", (d) => (out += d));
18	    proc.stderr.on("data", (d) => (err += d));
19	    proc.on("error", (e) => {
20	      clearTimeout(timer);
21	      reject(e);
22	    });
23	    proc.on("close", (code) => {
24	      clearTimeout(timer);
25	      if (code === 0) resolve(out);
26	      else reject(new Error(`yt-dlp exited ${code}: ${err.trim().split("\n").pop() ?? ""}`));
