const fs=require("fs");const f="src/pipeline/runner.ts";let s=fs.readFileSync(f,"utf8");
s=s.replace(`import { eq, sql } from "drizzle-orm";`,`import { desc, eq, isNull, lt, or, sql } from "drizzle-orm";`);
s=s.replace(`      if (needsLetsPlay(d.id)) letsPlayPool.push({ gameId: d.id, title: d.title });`,`      queueLetsPlay(d.id, d.title);`);
s=s.replace(`function saveLetsPlay(`,`// Ids already waiting in the let\x27s play queue, so the scraper and the backfill never enqueue a game twice.
const letsPlayQueued = new Set<number>();

function queueLetsPlay(gameId: number, title: string) {
  if (letsPlayQueued.has(gameId) || !needsLetsPlay(gameId)) return;
  letsPlayQueued.add(gameId);
  letsPlayPool.push({ gameId, title });
}

/** Games already in the DB whose let\x27s play is missing or due for a refresh (e.g. crawled before the feature ran). */
function backfillLetsPlays(limit: number) {
  const rows = db
    .select({ id: games.id, title: games.title })
    .from(games)
    .leftJoin(letsplays, eq(letsplays.gameId, games.id))
    .where(or(isNull(letsplays.gameId), lt(letsplays.updatedAt, sql\`datetime(\x27now\x27, \x27-6 hours\x27)\`)))
    .orderBy(desc(games.releaseDate))
    .limit(limit * 3)
    .all();
  let queued = 0;
  for (const r of rows) {
    if (queued >= limit) break;
    const before = letsPlayQueued.size;
    queueLetsPlay(r.id, r.title);
